const fs = require('fs'), path = require('path'), cp = require('child_process');
const [pkg, work] = process.argv.slice(2);
const proj = path.join(work, 'proj');
fs.rmSync(proj, { recursive: true, force: true });
fs.mkdirSync(path.join(proj, '.claude'), { recursive: true });
let copy, bin;
// Published package or source checkout? Ask whether the zh-TW pack sits beside the package folder (`<repo>/locales/zh-TW` next to `<repo>/cli`).
// `bundled/` cannot tell them apart: a source checkout has it too once `prepack` has run, and then the copy below would sit in the repository
// root, where the development fallback of skills-installer.js finds `../locales/zh-TW` and the pack is not missing at all.
if (!fs.existsSync(path.join(path.dirname(pkg), 'locales', 'zh-TW'))) {
  // a published package: copy it next to its own dependencies and take the zh-TW pack out of the copy
  copy = path.join(path.dirname(pkg), 'uds-without-zh-tw');
  fs.rmSync(copy, { recursive: true, force: true });
  fs.cpSync(pkg, copy, { recursive: true });
  fs.rmSync(path.join(copy, 'bundled', 'locales', 'zh-TW'), { recursive: true, force: true });
  bin = path.join(copy, 'bin', 'uds.js');
} else {
  // a source checkout (--local-bin): stage cli/ beside links to the repository folders, minus locales/
  const repo = path.dirname(pkg);
  copy = path.join(work, 'stage');
  fs.rmSync(copy, { recursive: true, force: true });
  fs.mkdirSync(path.join(copy, 'cli'), { recursive: true });
  for (const d of ['bin', 'src']) fs.cpSync(path.join(pkg, d), path.join(copy, 'cli', d), { recursive: true });
  for (const f of ['package.json', 'standards-registry.json']) fs.copyFileSync(path.join(pkg, f), path.join(copy, 'cli', f));
  const link = (target, at) => fs.symlinkSync(target, at, fs.statSync(target).isDirectory() ? 'junction' : 'file');
  link(path.join(pkg, 'node_modules'), path.join(copy, 'cli', 'node_modules'));
  for (const name of fs.readdirSync(repo)) {
    if (['cli', '.git', 'node_modules', 'locales'].includes(name)) continue;
    link(path.join(repo, name), path.join(copy, name));
  }
  bin = path.join(copy, 'cli', 'bin', 'uds.js');
}
const r = cp.spawnSync(process.execPath, [bin, 'init', '--yes', '--locale', 'zh-tw'], { cwd: proj, encoding: 'utf8', env: process.env });
const skill = path.join(proj, '.claude', 'skills', 'commit-standards', 'SKILL.md');
const chinese = fs.existsSync(skill) && fs.readFileSync(skill, 'utf8').includes('# Commit Message 助手');
process.stdout.write((r.stdout || '') + (r.stderr || '') + '\nCHINESE-SKILL-TEXT=' + chinese + '\n');
fs.rmSync(copy, { recursive: true, force: true });
process.exit(r.status === null ? 1 : r.status);

const fs = require('fs'), path = require('path');
// Makes the copy of ONE standard fail the way a file held by antivirus fails: EBUSY, a set number of times.
const real = fs.copyFileSync;
const failTimes = process.env.UDS_FAKE_LOCK_FAIL_TIMES === 'always' ? Infinity : Number(process.env.UDS_FAKE_LOCK_FAIL_TIMES);
fs.copyFileSync = function (src, dest, ...rest) {
  if (path.basename(String(dest)) === 'error-codes.ai.yaml') {
    const log = process.env.UDS_FAKE_LOCK_LOG;
    const tries = (fs.existsSync(log) ? fs.readFileSync(log, 'utf8').split('\n').filter(Boolean).length : 0) + 1;
    fs.appendFileSync(log, 'try ' + tries + '\n');
    if (tries <= failTimes) {
      const err = new Error('EBUSY: resource busy or locked, copyfile');
      err.code = 'EBUSY'; err.syscall = 'copyfile';
      throw err;
    }
  }
  return real.call(this, src, dest, ...rest);
};

