import { spawnSync } from 'node:child_process';
// Runs `uds list` and compares two numbers the command itself prints: the sum of the category headings and the Total line.
const run = spawnSync(process.execPath, [process.argv[2], 'list'], { encoding: 'utf8' });
if (run.status !== 0) { console.log(`uds list exited ${run.status}`); process.exit(1); }
let listed = 0;
for (const line of run.stdout.split('\n')) {
  const heading = /^[A-Z][A-Za-z ]* \((\d+)\)$/.exec(line.trimEnd());
  if (heading) listed += Number(heading[1]);
}
const total = /Total: (\d+) standards/.exec(run.stdout);
console.log(`listed ${listed} of ${total ? total[1] : 'unknown'} standards`);

