import { createServer } from 'node:http';
import { spawn } from 'node:child_process';
// A stand-in npm registry: every package has 1.0.0 and 1.2.0 (latest). It answers after one second and counts the requests in flight.
const [bin, ...udsArgs] = process.argv.slice(2);
const known = ['alpha', 'beta', 'gamma', 'delta'];
let inflight = 0;
let most = 0;
const server = createServer((req, res) => {
  inflight += 1;
  most = Math.max(most, inflight);
  const name = decodeURIComponent(req.url.slice(1));
  setTimeout(() => {
    inflight -= 1;
    if (!known.includes(name)) { res.statusCode = 404; res.end('{"error":"not found"}'); return; }
    const manifest = (version) => ({ name, version, dist: { tarball: `http://127.0.0.1:${server.address().port}/${name}/-/${name}-${version}.tgz`, shasum: '0'.repeat(40) } });
    res.setHeader('content-type', 'application/json');
    res.end(JSON.stringify({ name, 'dist-tags': { latest: '1.2.0' }, versions: { '1.0.0': manifest('1.0.0'), '1.2.0': manifest('1.2.0') } }));
  }, 1000);
});
server.listen(0, '127.0.0.1', () => {
  const registry = `http://127.0.0.1:${server.address().port}/`;
  const child = spawn(process.execPath, [bin, ...udsArgs], { stdio: ['ignore', 'inherit', 'inherit'], env: { ...process.env, npm_config_registry: registry } });
  child.on('close', (code) => { console.log(`stand-in registry: most requests at once = ${most}`); server.close(); process.exitCode = code; });
});

